void MessengerWindow::openAccountProfile(const QString& path){
 try{accountOwner_=std::make_unique<AccountController>(path,this);}catch(const std::exception& error){notice_->setText(tr("This profile needs recovery (%1). Its data was kept.").arg(QString::fromUtf8(error.what())));return;}
 refresh_->setText(tr("Refresh"));detach_->hide();
 connect(accountOwner_.get(),&AccountController::nodeStopped,this,[this]{notice_->setText(tr("Node stopped. Unlock your device to start it again."));});
 connect(accountOwner_.get(),&AccountController::hostStatusReady,this,&MessengerWindow::updateNodeStatus);
 connect(accountOwner_.get(),&AccountController::busyChanged,this,[this](bool busy){working_=busy;if(busy)notice_->setText(tr("Working…"));else if(notice_->text()==tr("Working…"))notice_->clear();updateControls();});
 connect(accountOwner_.get(),&AccountController::rootUnlockRequired,this,[this]{needRoot_=hostStatus_.value("profileExists").toBool();notice_->setText(needRoot_?tr("Unlock your device to open your Accounts."):tr("Create a profile or import your existing conversations."));updateControls();});
 connect(accountOwner_.get(),&AccountController::accountsReady,this,[this](const QJsonArray& rows){accounts_=rows;needRoot_=false;notice_->setText(rows.isEmpty()?(hostStatus_.value("profileExists").toBool()?tr("Create an Account to start a conversation."):tr("Create a profile or import your existing conversations.")):tr("Sign in to open your conversations."));updateControls();if(startNodeAfterUnlock_){startNodeAfterUnlock_=false;accountOwner_->enableNode(pendingEndpoints_,pendingDirect_);}else if(createAfterUnlock_){createAfterUnlock_=false;createAccountDialog();}});
 connect(accountOwner_.get(),&AccountController::profileCreated,this,&MessengerWindow::createAccountDialog);
 connect(accountOwner_.get(),&AccountController::accountAdded,this,[this](const QJsonObject& row){accounts_.append(row);updateControls();});
 connect(accountOwner_.get(),&AccountController::signedIn,this,[this](const QJsonObject& v){loggedIn_=true;account_->setText(v.value("displayName").toString(tr("Account")));notice_->clear();updateControls();});
 connect(accountOwner_.get(),&AccountController::signedOut,this,[this]{loggedIn_=false;findChild<QStackedWidget*>("sidebarPages")->setCurrentIndex(0);peer_.clear();chats_->clear();history_->clear();compose_->clear();account_->setText(tr("Signed out"));chatTitle_->setText(tr("Your conversations"));notice_->setText(hostStatus_.value("nodeRunning").toBool()?tr("Signed out. Node keeps running."):tr("Sign in to continue."));updateControls();});
 connect(accountOwner_.get(),&AccountController::contactsReady,this,[this](const QJsonArray& rows){chats_->clear();for(const auto& value:rows){auto v=value.toObject();auto* item=new QListWidgetItem(v.value("name").toString(v.value("id").toString()),chats_);item->setData(Qt::UserRole,v.value("id").toString());item->setToolTip(v.value("state").toString());item->setData(Qt::UserRole+2,v.value("chatLocked").toBool()?tr("Conversation locked"):tr("Open conversation"));item->setData(Qt::UserRole+4,v.value("chatLocked").toBool());}chats_->setEnabled(true);if(chats_->count())chats_->setCurrentRow(0);});
 connect(accountOwner_.get(),&AccountController::historyReady,this,&MessengerWindow::showHistory);
 connect(accountOwner_.get(),&AccountController::sent,this,[this](const QJsonObject& v){if(v.value("accepted").toBool()){compose_->clear();accountOwner_->history(peer_);}else notice_->setText(tr("The message has not been accepted. Please try again."));});
 connect(accountOwner_.get(),&AccountController::failed,this,[this](const QString& code){notice_->setText(code=="ACCOUNT_SESSION_CHANGED"?tr("Action cancelled."):code.contains("PASSWORD")||code.contains("LOGIN")?tr("Could not sign in. Check your Account password."):tr("Could not complete this action (%1). Your stored data was kept.").arg(code));});
 accountOwner_->loadAccounts();updateControls();
}
void MessengerWindow::importAccountProfile(const QJsonObject& v){if(accountOwner_)rootUnlockDialog(v);}
bool MessengerWindow::rootUnlockDialog(const QJsonObject& profile){QDialog dialog(this);dialog.setObjectName("rootUnlockDialog");dialog.setWindowTitle(tr("Unlock device"));auto* layout=new QVBoxLayout(&dialog);auto* label=new QLabel(tr("Enter the device PIN for this profile."));layout->addWidget(label);auto* pin=new QLineEdit;pin->setObjectName("rootPin");pin->setEchoMode(QLineEdit::Password);pin->setPlaceholderText(tr("Device PIN"));layout->addWidget(pin);auto* buttons=new QDialogButtonBox(QDialogButtonBox::Ok|QDialogButtonBox::Cancel);buttons->button(QDialogButtonBox::Ok)->setText(tr("Unlock"));layout->addWidget(buttons);connect(buttons,&QDialogButtonBox::accepted,&dialog,[&]{auto value=pin->text();pin->clear();if(profile.isEmpty())accountOwner_->unlockRoot(value);else accountOwner_->importProfile(profile,value);dialog.accept();});connect(buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);return dialog.exec()==QDialog::Accepted;}
void MessengerWindow::updateControls(){const bool nodeRunning=hostStatus_.value("nodeRunning").toBool();nodeToggle_->setText(nodeRunning?tr("Stop Node & lock"):tr("Start Node"));nodeToggle_->setEnabled(accountOwner_&&!working_&&(hostStatus_.value("profileExists").toBool()||nodeRunning));nodeSettings_->setEnabled(nodeToggle_->isEnabled()&&!nodeRunning);if(accountOwner_)refresh_->setEnabled(!working_&&!hostStatus_.isEmpty());cancel_->setVisible(working_);login_->setVisible(!loggedIn_);login_->setText(needRoot_?tr("Unlock device"):tr("Sign in"));login_->setEnabled(accountOwner_&&(needRoot_||!accounts_.isEmpty())&&!working_);logout_->setVisible(loggedIn_);logout_->setEnabled(!working_);import_->setVisible(!loggedIn_);import_->setEnabled(accountOwner_&&!loggedIn_&&!working_);create_->setVisible(!loggedIn_);create_->setText(hostStatus_.value("profileExists").toBool()?tr("Create Account"):tr("Create profile"));create_->setEnabled(accountOwner_&&!working_&&!hostStatus_.isEmpty());chats_->setEnabled(loggedIn_&&!working_);compose_->setEnabled(loggedIn_&&!peer_.isEmpty()&&!working_&&!(chats_->currentItem()&&chats_->currentItem()->data(Qt::UserRole+4).toBool()));findChild<QPushButton*>("emoji")->setEnabled(compose_->isEnabled());send_->setEnabled(compose_->isEnabled()&&!compose_->toPlainText().trimmed().isEmpty());}
void MessengerWindow::createProfileDialog(){
 QDialog dialog(this);dialog.setObjectName("createProfileDialog");dialog.setWindowTitle(tr("Create your profile"));auto* layout=new QVBoxLayout(&dialog);auto* pin=new QLineEdit;pin->setObjectName("newRootPin");pin->setPlaceholderText(tr("Device PIN"));pin->setEchoMode(QLineEdit::Password);auto* confirm=new QLineEdit;confirm->setObjectName("confirmRootPin");confirm->setPlaceholderText(tr("Confirm PIN"));confirm->setEchoMode(QLineEdit::Password);layout->addWidget(pin);layout->addWidget(confirm);auto* error=new QLabel;error->setObjectName("createProfileError");error->setWordWrap(true);layout->addWidget(error);auto* buttons=new QDialogButtonBox(QDialogButtonBox::Ok|QDialogButtonBox::Cancel);buttons->button(QDialogButtonBox::Ok)->setText(tr("Create profile"));layout->addWidget(buttons);connect(buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);connect(buttons,&QDialogButtonBox::accepted,&dialog,[&]{if(pin->text().isEmpty()||pin->text()!=confirm->text()){error->setText(tr("Enter the same PIN in both fields."));return;}auto value=pin->text();pin->clear();confirm->clear();accountOwner_->createProfile(value);dialog.accept();});dialog.exec();
}
void MessengerWindow::createAccountDialog(){
 if(!accountOwner_)return;QDialog dialog(this);dialog.setObjectName("createAccountDialog");dialog.setWindowTitle(tr("Create Account"));auto* layout=new QVBoxLayout(&dialog);auto field=[&](const char* name,const QString& hint,bool secret){auto* input=new QLineEdit;input->setObjectName(name);input->setPlaceholderText(hint);if(secret)input->setEchoMode(QLineEdit::Password);layout->addWidget(input);return input;};auto* identity=field("newIdentity",tr("Account name"),false);auto* display=field("newDisplayName",tr("Display name (optional)"),false);auto* password=field("newAccountPassword",tr("Account password"),true);auto* confirm=field("confirmAccountPassword",tr("Confirm password"),true);auto* error=new QLabel;error->setObjectName("createAccountError");error->setWordWrap(true);layout->addWidget(error);auto* buttons=new QDialogButtonBox(QDialogButtonBox::Ok|QDialogButtonBox::Cancel);buttons->button(QDialogButtonBox::Ok)->setText(tr("Create and sign in"));layout->addWidget(buttons);connect(buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);connect(buttons,&QDialogButtonBox::accepted,&dialog,[&]{auto name=identity->text().trimmed(),secret=password->text();if(name.isEmpty()||secret.isEmpty()||secret!=confirm->text()){error->setText(tr("Enter an Account name and the same password in both fields."));return;}password->clear();confirm->clear();accountOwner_->createAndSignIn(name,secret,display->text().trimmed());dialog.accept();});dialog.exec();
}
void MessengerWindow::loginDialog(){if(needRoot_){rootUnlockDialog();return;}if(!accountOwner_||accounts_.isEmpty())return;QDialog d(this);d.setObjectName("loginDialog");d.setWindowTitle(tr("Sign in"));auto* layout=new QVBoxLayout(&d);auto* accounts=new QComboBox;accounts->setObjectName("accountChoice");for(const auto& value:accounts_){auto v=value.toObject();QString id=v.value("identity").toString(v.value("id").toString());accounts->addItem(v.value("name").toString(v.value("displayName").toString(id)),id);}layout->addWidget(accounts);auto* password=new QLineEdit;password->setObjectName("accountPassword");password->setEchoMode(QLineEdit::Password);password->setPlaceholderText(tr("Account password"));layout->addWidget(password);auto* buttons=new QDialogButtonBox(QDialogButtonBox::Ok|QDialogButtonBox::Cancel);buttons->button(QDialogButtonBox::Ok)->setText(tr("Sign in"));layout->addWidget(buttons);connect(buttons,&QDialogButtonBox::accepted,&d,[&]{auto text=password->text();password->clear();accountOwner_->login(accounts->currentData().toString(),text);d.accept();});connect(buttons,&QDialogButtonBox::rejected,&d,&QDialog::reject);d.exec();}
void MessengerWindow::showHistory(const QJsonArray& rows){notice_->clear();history_->setRows(rows);if(chats_->currentItem()&&!rows.isEmpty()){auto row=rows.last().toObject();chats_->currentItem()->setData(Qt::UserRole+2,row.value("text").toString());const auto time=row.value("time").toVariant().toLongLong();chats_->currentItem()->setData(Qt::UserRole+3,time?QDateTime::fromMSecsSinceEpoch(time).toLocalTime().toString("HH:mm"):QString());}updateControls();}

void MessengerWindow::updateNodeStatus(const QJsonObject& value){for(auto it=value.begin();it!=value.end();++it)hostStatus_[it.key()]=it.value();const bool running=hostStatus_.value("nodeRunning").toBool();if(!running)hostStatus_["node"]=QJsonObject{};if(!loggedIn_&&hostStatus_.value("profileExists").toBool())needRoot_=hostStatus_.value("rootLocked").toBool();auto node=hostStatus_.value("node").toObject();if(running&&!node.isEmpty()&&hostStatus_.value("nodeState").toString()!="unavailable"){const int peers=node.value("connectedPeers").toInt();status_->setText(peers?tr("Node running · %1 connected peers").arg(peers):tr("Node running · no peers connected"));}else if(running)status_->setText(tr("Node process running · checking connections…"));else status_->setText(tr("Node is off"));updateControls();}
void MessengerWindow::requestNodeStart(const QJsonArray& endpoints,bool direct){if(!accountOwner_)return;if(hostStatus_.value("rootLocked").toBool()){pendingEndpoints_=endpoints;pendingDirect_=direct;startNodeAfterUnlock_=true;if(!rootUnlockDialog())startNodeAfterUnlock_=false;}else accountOwner_->enableNode(endpoints,direct);}
void MessengerWindow::nodeSettings(){if(!accountOwner_)return;QDialog dialog(this);dialog.setObjectName("nodeSettingsDialog");dialog.setWindowTitle(tr("Node connections"));dialog.resize(650,360);auto* layout=new QVBoxLayout(&dialog);auto* description=new QLabel(tr("Use the connection details supplied by your network. Empty connections keep Node available locally until a peer is configured."));description->setWordWrap(true);layout->addWidget(description);auto* table=new QTableWidget(0,2);table->setObjectName("nodeConnections");table->setHorizontalHeaderLabels({tr("Server address"),tr("Node key")});table->horizontalHeader()->setSectionResizeMode(QHeaderView::Stretch);auto policy=hostStatus_.value("nodePolicy").toObject();for(const auto& item:policy.value("endpoints").toArray()){auto row=item.toObject();int n=table->rowCount();table->insertRow(n);table->setItem(n,0,new QTableWidgetItem(row.value("url").toString()));table->setItem(n,1,new QTableWidgetItem(row.value("nodeId").toString()));}layout->addWidget(table,1);auto* row=new QHBoxLayout;auto* add=new QPushButton(tr("Add"));add->setObjectName("addConnection");auto* remove=new QPushButton(tr("Remove"));remove->setObjectName("removeConnection");row->addWidget(add);row->addWidget(remove);row->addStretch();layout->addLayout(row);connect(add,&QPushButton::clicked,&dialog,[table]{int n=table->rowCount();table->insertRow(n);table->setItem(n,0,new QTableWidgetItem);table->setItem(n,1,new QTableWidgetItem);table->setCurrentCell(n,0);table->editItem(table->item(n,0));});connect(remove,&QPushButton::clicked,&dialog,[table]{if(table->currentRow()>=0)table->removeRow(table->currentRow());});auto* direct=new QCheckBox(tr("Allow direct connections"));direct->setObjectName("directConnections");direct->setChecked(policy.value("directEnabled").toBool());layout->addWidget(direct);auto* error=new QLabel;error->setObjectName("connectionError");error->setWordWrap(true);layout->addWidget(error);auto* buttons=new QDialogButtonBox(QDialogButtonBox::Ok|QDialogButtonBox::Cancel);buttons->button(QDialogButtonBox::Ok)->setText(tr("Start Node"));layout->addWidget(buttons);connect(buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);connect(buttons,&QDialogButtonBox::accepted,&dialog,[&]{QJsonArray endpoints;for(int row=0;row<table->rowCount();row++){const auto url=table->item(row,0)?table->item(row,0)->text().trimmed():QString();const auto key=table->item(row,1)?table->item(row,1)->text().trimmed():QString();QUrl parsed(url);if((parsed.scheme()!="ws"&&parsed.scheme()!="wss")||parsed.host().isEmpty()||key.size()!=64){error->setText(tr("Enter a ws:// or wss:// server address and its 64-character Node key."));return;}endpoints.append(QJsonObject{{"url",url},{"nodeId",key}});}dialog.accept();requestNodeStart(endpoints,direct->isChecked());});dialog.exec();}
